const table = (headers, rows)=>`<div class="surface table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>{let index=0;return row.replace(/<td(?=[ >])/g,()=>'<td data-label="'+esc(headers[index++]||'')+'"');}).join('')||`<tr><td colspan="${headers.length}" class="empty">暂无内容</td></tr>`}</tbody></table></div>`;
function audit(text,type='操作'){activity.unshift({actor:'Jack Lu',text,type,time:'刚刚'});}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function closeModal(){$('#modal').close();}
function modal(heading,body,foot=''){ $('#modal').classList.remove('credential-dialog','membership-dialog'); $('#modal-content').innerHTML=`<div class="modal-head"><h2>${heading}</h2><button class="icon-button" data-action="close" aria-label="关闭弹窗">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${btn('取消','close')}${foot}</div>`:''}`;$('#modal').showModal();}
function formModal(heading,body,submit,label='保存'){modal(heading,`<form id="active-form" data-submit="${submit}">${body}<button hidden type="submit"></button></form>`,`<button class="btn primary" type="submit" form="active-form">${label}</button>`);}
function field(label,name,type='text',value='',extra=''){return `<label class="field ${extra}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='password'?'autocomplete="new-password"':''} required></label>`;}
const selectField = (label,name,opts)=>`<label class="field">${label}<select name="${name}">${opts.map(([value,label])=>`<option value="${esc(value)}">${esc(label)}</option>`).join('')}</select></label>`;
const canWrite = ()=>state.role!=='viewer'&&['owner','developer'].includes(userProjectRole())&&contextAvailable();
const canAdmin = ()=>state.role==='owner'&&(userProjectRole()==='owner'||['owner','admin'].includes(userTenantRole()));
function guard(admin=false){if(admin?!canAdmin():!canWrite()){toast('当前预览角色无此操作权限，可在个人菜单切换角色');return false;}return true;}
function stats(){return `<div class="stats">${[['待处理问题',issues.filter(i=>i.status==='todo').length,issues.length?'本周新增 3 个':'暂无新增问题','◫'],['进行中',issues.filter(i=>i.status==='in_progress').length,'<strong>'+sessions.filter(s=>s.status==='进行中').length+' 个</strong> Agent 会话正在运行','◷'],['本周已解决',issues.filter(i=>i.status==='done').length,'<strong>↑ 2</strong> 较上周','✓'],['在线实例',instances.filter(i=>i.health==='健康').length+' <span style="font-size:15px;color:#adb5ad;font-weight:400">/ '+instances.length+'</span>','1 个实例需要关注','◇']].map(([label,value,note,symbol])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-symbol">${symbol}</span></div><div class="stat-value">${value}${label==='本周已解决'&&issues.some(i=>i.status==='done')?'<small>↑ 100%</small>':''}</div><div class="stat-note">${note}</div></div>`).join('')}</div>`;}
function projectStrip(){return `<div class="surface project-strip"><span class="project-icon">▧</span><div><strong>${esc(state.project)}</strong><small>让每一个 Agent，都在正确的边界内协作。</small></div><div class="members">${Object.keys(people).map(avatar).join('')}</div><span class="muted" style="font-size:10px">${members.length} 位成员</span><span class="divider"></span>${badge('◇ 独立工作区','green')}${btn('项目设置 ↗','goto-settings',false,'style="font-size:10px;padding:6px 9px"')}</div>`;}
function activities(full=false){return `<div class="surface panel ${full?'activity-page':''}"><div class="panel-title"><h2>项目动态</h2>${full?badge('仅含操作元数据'): '<a class="text-link" href="#audit">查看全部 ↗</a>'}</div>${activity.slice(0,full?30:3).map((a,i)=>`<div class="activity-row"><span class="avatar ${['green','blue','purple'][i%3]}">${esc(a.actor.split(' ').map(n=>n[0]).join(''))}</span><div><strong>${esc(a.actor)}</strong> ${esc(a.text)}${full?` ${badge(a.type)}`:''}</div><time>${a.time}</time></div>`).join('')}</div>`;}
function healthPanel(){return `<div class="surface panel"><div class="panel-title"><h2>运行环境</h2><a class="text-link" href="#instances">管理实例 ↗</a></div><div class="health-row"><span class="engine-logo">⌘</span><div>OpenCode<small> · 远程实例</small></div>${badge('● '+instances.filter(i=>i.health==='健康').length+' 在线','green')}</div><div class="health-row"><span class="engine-logo">✳</span><div>Claude Agent SDK<small> · Phase 3</small></div>${badge('规划中')}</div><p class="inline-note" style="margin-bottom:0">配置 Bundle v1.${state.bundle} <span style="margin:0 8px">·</span> 公共文件 revision ${state.fileRevision}</p></div>`;}
function filteredIssues(){return issues.filter(i=>(state.assignee==='all'||i.owner===state.assignee)&&(state.priority==='all'||i.priority===state.priority)&&(`${i.title} ${esc(currentProject()?.key||'AH')}-${i.id} ${i.tags.join(' ')}`).toLowerCase().includes(state.query.toLowerCase()));}
function issueCard(i){return `<article class="issue" tabindex="0" role="button" aria-label="查看 ${esc(currentProject()?.key||'AH')}-${i.id} ${esc(i.title)}" draggable="${canWrite()}" data-issue="${i.id}"><div class="issue-top"><span>${esc(currentProject()?.key||'AH')}-${i.id}</span><span class="priority ${i.priority.toLowerCase()}">▰ ${i.priority}</span></div><h3>${esc(i.title)}</h3><p>${esc(i.desc)}</p><div class="labels">${i.tags.map((t,n)=>`<span class="tag ${t==='OpenCode'||t==='前端'?'blue':t==='配置中心'||t==='凭据'?'purple':''}">${esc(t)}</span>`).join('')}</div>${i.status==='in_progress'&&(i.session||i.linkedOther)?`<div class="issue-session"><i class="dot"></i> ${i.owner==='Jack'?'Agent 正在处理':'已关联成员会话 · 仅元数据'}</div>`:i.status==='in_review'?`<div class="issue-session review">◇ 等待人工确认</div>`:''}<div class="issue-bottom">${avatar(i.owner)}<span>${people[i.owner]?.[1]?.split(' ')[0]||i.owner}</span><span class="date">${i.status==='done'?'✓ ':''}${esc(i.date)}</span></div></article>`;}
function boardContent(){const list=filteredIssues();return state.view==='board'?`<div class="board-status-tabs">${statuses.map(([key,label])=>`<button data-action="board-column" data-value="${key}" class="${state.boardColumn===key?'active':''}">${label} <span>${list.filter(i=>i.status===key).length}</span></button>`).join('')}</div><div class="board" data-column="${state.boardColumn}">${statuses.map(([key,label,color])=>`<section class="column" data-status="${key}" aria-label="${label}"><div class="column-head"><i class="dot ${color}"></i>${label}<span class="column-count">${list.filter(i=>i.status===key).length}</span><button aria-label="在${label}新建问题" data-action="new-issue" data-value="${key}">+</button></div>${list.filter(i=>i.status===key).map(issueCard).join('')}${btn('＋ 添加问题','new-issue',false,`data-value="${key}" style="border:0;background:none;color:#9ba89c;padding:8px 3px;font-size:10px"`)}</section>`).join('')}</div>`:table(['问题','优先级','状态','负责人','关联'],list.map(i=>`<tr><td><button data-action="issue" data-value="${i.id}"><small>${esc(currentProject()?.key||'AH')}-${i.id}</small><strong>${esc(i.title)}</strong></button></td><td>${badge(i.priority,i.priority==='P0'?'red':'orange')}</td><td>${badge(statuses.find(s=>s[0]===i.status)?.[1]||'已取消')}</td><td>${avatar(i.owner)}${esc(i.owner)}</td><td>${i.session||i.linkedOther?'已关联会话':'—'}</td></tr>`));}
function board(){return title('项目看板','将想法变成行动，与 Agent 一起推进每一个问题。',`${btn('项目动态','project-pulse')}${btn('↗ 导出问题','export')}${btn('＋ 新建问题','new-issue',true)}`)+stats()+`<div class="toolbar"><div class="view-toggle"><button data-action="view" data-value="board" class="${state.view==='board'?'active':''}">▥ 看板视图</button><button data-action="view" data-value="list" class="${state.view==='list'?'active':''}">☷ 列表视图</button></div><div class="filters"><label class="search"><span class="sr-only">搜索问题</span><input id="issue-search" value="${esc(state.query)}" placeholder="搜索问题…"></label><select id="assignee-filter" aria-label="按成员筛选"><option value="all">所有成员</option>${Object.keys(people).map(p=>`<option value="${p}" ${state.assignee===p?'selected':''}>${people[p][1]}</option>`).join('')}</select><select id="priority-filter" aria-label="按优先级筛选"><option value="all">所有优先级</option>${['P0','P1','P2','P3'].map(p=>`<option ${state.priority===p?'selected':''}>${p}</option>`).join('')}</select>${btn('↺','reset-filter',false,'aria-label="重置筛选"')}</div></div><div id="board-content">${boardContent()}</div><button class="cancelled-toggle" data-action="cancelled">▸ 已取消的问题 (${issues.filter(i=>i.status==='cancelled').length})</button>`;}
function overview(){return title('每一次协作，都有新的进展。','下午好，Jack。这里是你的项目运行概况。',btn('进入我的工作台 ↗','goto-workbench',true))+stats()+`<div class="banner">◇ 项目边界已就绪：成员使用独立工作区，Provider 凭据由 Hub 注入，公共资料以只读方式同步。</div><div class="grid-2"><div class="surface panel"><div class="panel-title"><h2>我的待办</h2><a href="#board" class="text-link">打开看板 ↗</a></div>${issues.filter(i=>i.owner==='Jack'&&i.status!=='done').slice(0,3).map(issueCard).join('')}</div><div>${healthPanel()}<div style="margin-top:18px">${activities()}</div><div class="surface panel" style="margin-top:18px"><div class="panel-title"><h2>交付阶段</h2>${badge('Phase 1','green')}</div><p class="inline-note">当前：远程接入 · 配置下发 · 公共空间 · 项目看板</p><div class="metric-bar"><i style="width:38%"></i></div><p class="inline-note">下一阶段：托管编排 → 双引擎对齐 → 生产加固</p></div></div></div>`;}
function instancePage(){return title('运行实例','集中登记与管理运行时，通过 Hub 安全连接你的个人工作区。',btn('＋ 登记远程实例','new-instance',true))+`<div class="banner">◇ external 实例仅绑定一个成员工作区。节点地址与认证由控制平面保存，成员通过 Hub 访问。</div>`+table(['实例 / 引擎','模式','工作区归属','健康状态','同步组件','延迟','操作'],instances.map((r,i)=>`<tr><td><strong>${esc(r.name)}</strong><small>${esc(r.engine)}</small></td><td>${badge(r.mode)}</td><td>${esc(r.owner)}<small>独立工作区</small></td><td>${badge('● '+r.health,r.health==='健康'?'green':'red')}</td><td>${badge(r.sync?'agenthub-sync 已连接':'未连接',r.sync?'green':'orange')}</td><td>${r.latency}</td><td>${btn('检测','test-instance',false,`data-value="${i}"`)} ${btn('详情','instance-detail',false,`data-value="${i}"`)}</td></tr>`))+`<div class="bottom-grid"><div class="surface panel"><div class="panel-title"><h2>项目实例绑定</h2>${badge('OpenCode')}</div><p class="inline-note">当前项目仅允许绑定已登记的 OpenCode 实例。会话创建前将验证成员归属、配置同步与公共文件状态。</p>${btn('管理绑定','binding')}</div><div class="surface panel"><div class="panel-title"><h2>双引擎演进</h2>${badge('Phase 3')}</div><p class="inline-note">Claude Agent SDK 与 OpenCode 共用会话契约。Claude 运行时将在第三阶段开放；首版沿用 OpenCode 工作台。</p></div></div>`;}
